const fs = require('fs');
const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
let idx = 0;
const E = data[idx++];
const R = data[idx++];
const adj = Array.from({length: E+1}, () => []);
const edges = [];
for (let i = 0; i < R; i++) {
  const A = data[idx++];
  const B = data[idx++];
  const C = data[idx++];
  edges.push({u: A, v: B, w: C});
  adj[A].push({to: B, w: C, id: i});
  adj[B].push({to: A, w: C, id: i});
}

// Bridge finding (iterative DFS)
const disc = new Array(E+1).fill(0);
const low = new Array(E+1).fill(0);
const parent = new Array(E+1).fill(0);
const parentEdge = new Array(E+1).fill(-1);
const isBridge = new Array(R).fill(false);
let time = 0;

for (let start = 1; start <= E; start++) {
  if (disc[start] !== 0) continue;
  const stack = [{u: start, parentEdge: -1, edgeIdx: 0}];
  disc[start] = low[start] = ++time;
  while (stack.length > 0) {
    const frame = stack[stack.length - 1];
    const u = frame.u;
    if (frame.edgeIdx < adj[u].length) {
      const e = adj[u][frame.edgeIdx++];
      const v = e.to;
      const id = e.id;
      if (id === frame.parentEdge) continue;
      if (disc[v] === 0) {
        parent[v] = u;
        parentEdge[v] = id;
        disc[v] = low[v] = ++time;
        stack.push({u: v, parentEdge: id, edgeIdx: 0});
      } else {
        low[u] = Math.min(low[u], disc[v]);
      }
    } else {
      stack.pop();
      if (stack.length > 0) {
        const p = stack[stack.length - 1].u;
        low[p] = Math.min(low[p], low[u]);
        if (low[u] > disc[p]) {
          isBridge[parentEdge[u]] = true;
        }
      }
    }
  }
}

// Find cycles
const visitedCycle = new Array(E+1).fill(false);
const cycles = [];
for (let i = 1; i <= E; i++) {
  if (visitedCycle[i]) continue;
  let hasNonBridge = false;
  for (const e of adj[i]) {
    if (!isBridge[e.id]) {
      hasNonBridge = true;
      break;
    }
  }
  if (!hasNonBridge) continue;

  let curr = i;
  let prev = -1;
  const vertices = [];
  let length = 0;
  while (true) {
    visitedCycle[curr] = true;
    vertices.push(curr);
    let next = -1;
    let w = 0;
    for (const e of adj[curr]) {
      if (!isBridge[e.id] && e.to !== prev) {
        next = e.to;
        w = e.w;
        break;
      }
    }
    if (next === -1) break;
    length += w;
    prev = curr;
    curr = next;
    if (curr === i) break;
  }
  cycles.push({vertices, length});
}

// MinHeap
class MinHeap {
  constructor() {
    this.heap = [];
  }
  push(node, dist) {
    this.heap.push({node, dist});
    this.bubbleUp(this.heap.length - 1);
  }
  pop() {
    if (this.heap.length === 0) return null;
    const min = this.heap[0];
    const last = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0);
    }
    return min;
  }
  bubbleUp(idx) {
    while (idx > 0) {
      const parent = (idx - 1) >> 1;
      if (this.heap[parent].dist <= this.heap[idx].dist) break;
      [this.heap[parent], this.heap[idx]] = [this.heap[idx], this.heap[parent]];
      idx = parent;
    }
  }
  bubbleDown(idx) {
    const length = this.heap.length;
    while (true) {
      let left = (idx << 1) + 1;
      let right = left + 1;
      let smallest = idx;
      if (left < length && this.heap[left].dist < this.heap[smallest].dist) smallest = left;
      if (right < length && this.heap[right].dist < this.heap[smallest].dist) smallest = right;
      if (smallest === idx) break;
      [this.heap[smallest], this.heap[idx]] = [this.heap[idx], this.heap[smallest]];
      idx = smallest;
    }
  }
}

function dijkstra(start, E, adj) {
  const dist = new Array(E+1).fill(Infinity);
  dist[start] = 0;
  const heap = new MinHeap();
  heap.push(start, 0);
  while (heap.heap.length > 0) {
    const {node, dist: d} = heap.pop();
    if (d > dist[node]) continue;
    for (const edge of adj[node]) {
      const next = edge.to;
      const nd = d + edge.w;
      if (nd < dist[next]) {
        dist[next] = nd;
        heap.push(next, nd);
      }
    }
  }
  return dist;
}

const K = data[idx++];
const output = [];
for (let q = 0; q < K; q++) {
  const X = data[idx++];
  const T = data[idx++];
  const dist = dijkstra(X, E, adj);
  let ans = Infinity;
  for (const cycle of cycles) {
    if (cycle.length >= T) {
      let minDist = Infinity;
      for (const v of cycle.vertices) {
        if (dist[v] < minDist) minDist = dist[v];
      }
      if (minDist !== Infinity) {
        const cand = 2 * minDist + cycle.length;
        if (cand < ans) ans = cand;
      }
    }
  }
  output.push(ans === Infinity ? -1 : ans);
}
console.log(output.join('\n'));
